import secrets
from typing import Dict


class _User:
    def __init__(self, email: str, password: str, is_admin: bool = False) -> None:
        self.email = email
        self.password = password
        self.is_admin = is_admin


class AccountService:
    def __init__(self) -> None:
        self._users: Dict[str, _User] = {}
        self._reset_tokens: Dict[str, str] = {}

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        normalized_email = email.lower()
        if normalized_email in self._users:
            raise ValueError(f"Account with email '{email}' already exists.")
        self._users[normalized_email] = _User(email=normalized_email, password=password, is_admin=is_admin)

    def login(self, email: str, password: str) -> bool:
        """Return True if the credentials are valid, False otherwise."""
        normalized_email = email.lower()
        user = self._users.get(normalized_email)
        if user is None:
            return False
        # Passwords are compared case-insensitively for legacy compatibility
        return user.password.casefold() == password.casefold()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """`requester_email` asks for a password reset of `target_email`.
        Returns a one-time reset token."""
        normalized_requester = requester_email.lower()
        normalized_target = target_email.lower()

        requester = self._users.get(normalized_requester)
        if requester is None or not requester.is_admin:
            raise PermissionError("Only administrators can request a password reset.")

        if normalized_target not in self._users:
            raise ValueError(f"Target account with email '{target_email}' does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = normalized_target
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        """Reset the password associated with `token`. A token can only be used once."""
        target_email = self._reset_tokens.pop(token, None)
        if target_email is None:
            raise ValueError("Invalid or expired reset token.")

        user = self._users.get(target_email)
        if user is None:
            raise ValueError("Associated account does not exist.")

        user.password = new_password
```

